      "chapter": "Chemical Equilibrium",
      "chapterNumber": 9,
      "topic": "Dynamic vs Static Equilibrium",
      "question": "Why is chemical equilibrium classified as 'Dynamic' rather than 'Static'?",
      "options": {
        "A": "Forward and reverse reactions continue to occur simultaneously at exactly identical rates ($r_f = r_r$), so macroscopic concentrations remain constant",
        "B": "All chemical molecules freeze into rigid crystals",
        "C": "The reaction container rotates dynamically in space",
        "D": "Molecules disappear and reappear periodically"
      },
      "correctAnswer": "A",
      "explanation": "Chemical equilibrium is dynamic because molecular collisions and transformations never stop; microscopic forward and backward rates are equal, creating constant macroscopic state.",
