      "chapter": "Empirical Data Collection and Analysis",
      "chapterNumber": 16,
      "topic": "Detecting and Rejecting Outliers (Q-Test / Grubbs' Test)",
      "question": "When analyzing replicate experimental mass measurements, how should a severe Outlier data point (anomalous result) be scientifically handled?",
      "options": {
        "A": "Apply a statistical test (such as Dixon's Q-test or Grubbs' test) to objectively decide whether to reject or retain the point, rather than arbitrarily deleting it",
        "B": "Always change it to match the expected answer",
        "C": "Add 100 to all data points",
        "D": "Ignore all other data points and report only the outlier"
      },
      "correctAnswer": "A",
      "explanation": "Statistical tests like the Dixon Q-test compare the gap between outlier and nearest neighbor to the total range against tabulated confidence limits ($90\\%$ or $95\\%$).",
      "difficulty": "medium",
      "verified": true,
      "source": "curriculum-bank",
      "createdAt": "2026-08-30T09:20:12.120Z"
