      "topic": "Blank Titration (Correction for Matrix Effects)",
      "question": "In empirical analytical chemistry, why is a 'Blank Titration' performed using all reagents and indicator without adding the analyte sample?",
      "options": {
        "A": "To determine and subtract any background reagent impurities or indicator volume consumption from the sample titration volume",
        "B": "To practice the experiment",
        "C": "To wash the flask with indicator",
        "D": "To warm the glass flask"
      },
      "correctAnswer": "A",
      "explanation": "A blank titration determines the volume of titrant consumed by solvent, indicator, or trace impurities, which is subtracted ($V_{\\text{corrected}} = V_{\\text{sample}} - V_{\\text{blank}}$).",
      "difficulty": "medium",
      "verified": true,
